package com.safecall.model;

public class CallRecord {
    private long id;
    private String phoneNumber;
    private long timestamp;
    private int durationSeconds;
    private int urgencyScore;
    private String urgencyLevel;
    private String explanation;
    private CallOutcome callOutcome;
    private boolean isSimulation;

    /**
     * Complete constructor — preferred for all new records.
     * @param callOutcome The deterministic call outcome from CallLog or CallOutcome.UNKNOWN.
     * @param isSimulation True if this record was generated by a UI simulation and must not pollute baselines.
     */
    public CallRecord(long id, String phoneNumber, long timestamp, int durationSeconds,
                      int urgencyScore, String urgencyLevel, String explanation,
                      CallOutcome callOutcome, boolean isSimulation) {
        this.id = id;
        this.phoneNumber = phoneNumber;
        this.timestamp = timestamp;
        this.durationSeconds = durationSeconds;
        this.urgencyScore = urgencyScore;
        this.urgencyLevel = urgencyLevel;
        this.explanation = explanation;
        this.callOutcome = (callOutcome != null) ? callOutcome : CallOutcome.UNKNOWN;
        this.isSimulation = isSimulation;
    }

    /**
     * Constructor without explicit simulation flag (defaults to real call: isSimulation=false).
     */
    public CallRecord(long id, String phoneNumber, long timestamp, int durationSeconds,
                      int urgencyScore, String urgencyLevel, String explanation,
                      CallOutcome callOutcome) {
        this(id, phoneNumber, timestamp, durationSeconds, urgencyScore, urgencyLevel,
                explanation, callOutcome, false);
    }

    /**
     * Backward-compatible constructor — callOutcome defaults to UNKNOWN, isSimulation=false.
     * Kept so legacy callers (SafeCallNativeBridge, test helpers) compile without changes.
     */
    public CallRecord(long id, String phoneNumber, long timestamp, int durationSeconds,
                      int urgencyScore, String urgencyLevel, String explanation) {
        this(id, phoneNumber, timestamp, durationSeconds, urgencyScore, urgencyLevel,
                explanation, CallOutcome.UNKNOWN, false);
    }

    public long getId() { return id; }
    public String getPhoneNumber() { return phoneNumber; }
    public long getTimestamp() { return timestamp; }
    public int getDurationSeconds() { return durationSeconds; }
    public int getUrgencyScore() { return urgencyScore; }
    public String getUrgencyLevel() { return urgencyLevel; }
    public String getExplanation() { return explanation; }
    public CallOutcome getCallOutcome() { return callOutcome; }
    public boolean isSimulation() { return isSimulation; }
}
